// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 amount, address actor) public {
        amount = bound(amount, 0, 1000 ether);
        vm.assume(actor != address(0) && actor != address(c));
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: amount}("");
        // General rule: the call succeeds if and only if exactly 10 ether is sent.
        assertTrue(ok == (amount == 10 ether));
    }
}
